//! Wolfram Newton-system replay.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/newton_golden.wls`) carries exact solutions, residuals and
//! Jacobians for F(x,y) = (x^2+y^2-2, x-y), per
//! audit-sonium-solvers-nonlinear-20260921. Newton iterates are
//! implementation-specific and asserted only by convergence to the Wolfram
//! branch; residuals and Jacobians are pinned exactly.

use serde::Deserialize;
use sonium_solvers_nonlinear::{LineSearch, NewtonConfig, newton_raphson};

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Probe {
    point: Vec<String>,
    residual: Vec<String>,
    jacobian: Vec<Vec<String>>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    solutions: Vec<Vec<String>>,
    probes: Vec<Probe>,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Newton-system fixture");
    assert_eq!(fixture.schema, "sonium-solvers-nonlinear.wolfram-golden.v1");
    fixture
}

fn residual(point: &[f64]) -> Vec<f64> {
    let (x, y) = (point[0], point[1]);
    vec![x * x + y * y - 2.0, x - y]
}

/// Exact 2x2 Jacobian solve by Cramer's rule (independent of any solver).
fn jacobian_solve(point: &[f64], rhs: &[f64]) -> Result<Vec<f64>, String> {
    let (x, y) = (point[0], point[1]);
    let (a, b, c, d) = (2.0 * x, 2.0 * y, 1.0, -1.0);
    let det = a * d - b * c;
    if det == 0.0 {
        return Err("singular Jacobian".to_string());
    }
    Ok(vec![
        (d * rhs[0] - b * rhs[1]) / det,
        (-c * rhs[0] + a * rhs[1]) / det,
    ])
}

fn config() -> NewtonConfig {
    NewtonConfig {
        max_iterations: 50,
        absolute_tolerance: 1e-12,
        relative_tolerance: 1e-12,
        damping: 1.0,
        line_search: LineSearch::None,
        ..Default::default()
    }
}

#[test]
fn newton_converges_to_wolfram_branch() {
    let fixture = parse_fixture();
    assert_eq!(fixture.solutions.len(), 2);
    let solution =
        newton_raphson(&[2.0, 0.5], residual, jacobian_solve, &config()).expect("newton converged");
    assert!(solution.converged);
    let expected: Vec<f64> = fixture.solutions[0]
        .iter()
        .map(|value| parse(value))
        .collect();
    assert_eq!(expected, vec![1.0, 1.0]);
    for (got, want) in solution.x.iter().zip(expected.iter()) {
        assert!(
            (got - want).abs() <= 1e-9,
            "newton x = {:?}, wolfram {expected:?}",
            solution.x
        );
    }
}

#[test]
fn residual_and_jacobian_match_wolfram() {
    let fixture = parse_fixture();
    assert_eq!(fixture.probes.len(), 3);
    for probe in &fixture.probes {
        let point: Vec<f64> = probe.point.iter().map(|value| parse(value)).collect();
        let expected_residual: Vec<f64> = probe.residual.iter().map(|value| parse(value)).collect();
        let actual = residual(&point);
        for (index, (got, want)) in actual.iter().zip(expected_residual.iter()).enumerate() {
            assert!(
                (got - want).abs() <= 1e-12 * want.abs().max(1.0),
                "residual[{index}]: {got:e} != {want:e}"
            );
        }
        assert_eq!(probe.jacobian.len(), 2);
        for (i, row) in probe.jacobian.iter().enumerate() {
            for (j, want) in row.iter().enumerate() {
                let want = parse(want);
                let got = if i == 0 {
                    [2.0 * point[0], 2.0 * point[1]][j]
                } else {
                    [1.0, -1.0][j]
                };
                assert!(
                    (got - want).abs() <= 1e-15,
                    "jacobian[{i},{j}]: {got:e} != {want:e}"
                );
            }
        }
    }
}
